    reqParams.set(SCHEMA_VERSION_PARAM, String.valueOf(schemaVersion));
    reqParams.set(CONFIG_SET_PARAM, configSet);
    req = mock(SolrQueryRequest.class);
    when(req.getParams()).thenReturn(reqParams);
