    when(mockReq.getHeader(any(String.class))).then(invocation -> {
        if (headerKey.equals(invocation.getArgument(0))) {
            if (header.get() == null)
                return null;
            return header.get().getValue();
        } else
            return null;
    });
    when(mockReq.getRequestURI()).thenReturn("/collection1/select");
    return mockReq;
}

